#include <bits/stdc++.h>
using namespace std;

int main() {
    int a, b, c, n;
    scanf("%d%d%d%d", &a, &b, &c, &n);

    int ans = n - (a + b - c);

    if (ans > 0 && a < n && b < n && c < n &&
        n - ans >= a && n - ans >= b && n - ans >= c &&
        c <= a && c <= b && ans <= n) {
        cout << ans << '\n';
    } else {
        cout << -1 << '\n';
    }

    return 0;
}

